;(()=>{try{
/* ===== Tiện ích thêm cho bản Việt hóa (sa pé): "Xem điện thoại" + "Không gian tình nhân" =====
   Ý tưởng tính năng lấy từ 兔k机 EPhone; code viết lại cho Abstract外置手机. Dữ liệu lưu trong biến chat (riêng từng đoạn chat). */
const W=(()=>{try{return window.parent&&window.parent!==window?window.parent:window}catch{return window}})();
const D=W.document;
const SID=(()=>{try{return typeof getScriptId==='function'?String(getScriptId()):''}catch{return''}})();
const KEY='ab_tuk';
const getRoot=()=>{const h=D.getElementById(`improved-phone-shadow-host-${SID||'default'}`)||D.querySelector('[id^="improved-phone-shadow-host-"]');return h&&h.shadowRoot||null};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,7);
const pad=n=>String(n).padStart(2,'0');
const stamp=()=>{const d=new Date();return`${pad(d.getMonth()+1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`};
const toast=(m,t)=>{try{const T=W.toastr||(typeof toastr!=='undefined'?toastr:null);T&&(T[t||'info']||T.info).call(T,m)}catch{}};
const arr=x=>Array.isArray(x)?x:[];

/* ---------- dữ liệu ---------- */
const loadAll=()=>{try{const v=getVariables({type:'chat'})||{};return JSON.parse(JSON.stringify(v[KEY]||{}))}catch{return{}}};
const saveAll=d=>{try{const v=JSON.parse(JSON.stringify(getVariables({type:'chat'})||{}));v[KEY]=d;replaceVariables(v,{type:'chat'});return!0}catch(e){console.error('[Tuk addon] Lưu thất bại:',e);toast('Lưu dữ liệu thất bại','error');return!1}};
const charData=name=>{const a=loadAll();const c=a[name]||{};c.phone=c.phone||{};c.lovers=c.lovers||{};c.lovers.moments=arr(c.lovers.moments);c.lovers.photos=arr(c.lovers.photos);c.lovers.letters=arr(c.lovers.letters);return c};
const putChar=(name,c)=>{const a=loadAll();a[name]=c;return saveAll(a)};
const people=()=>{let user={name:'',avatar:''},chars=[];
  try{const v=getVariables({type:'character'})||{};const p=v.phone_data||{};
    if(p.user)user={name:String((/^(昵称|Biệt danh)$/.test(String(p.user.nickname||'').trim())?'':p.user.nickname)||p.user.name||'').trim(),avatar:p.user.avatar||''};
    const NN=x=>{const t=String(x||'').trim();return!t||/^(昵称|Biệt danh|nickname)$/i.test(t)?'':t};chars=arr(p.characters).filter(c=>c&&c.name).map(c=>({name:String(c.name),nick:NN(c.nickname)||String(c.name),avatar:c.avatar||''}))}catch{}
  try{if(!user.name)user.name=String(SillyTavern.name1||'').trim()}catch{}
  if(!user.name)user.name='Tôi';
  if(!chars.length){let n='';try{n=String(SillyTavern.name2||'').trim()}catch{}chars=[{name:n||'Người ấy',nick:n||'Người ấy',avatar:''}]}
  return{user,chars}};

/* ---------- gọi AI ---------- */
const parseAI=async content=>{let t=String(content??'');
  for(const tag of['</think>','</thinking>']){const i=t.lastIndexOf(tag);if(i!==-1)t=t.slice(i+tag.length)}
  const m=t.match(/<tuk_data>([\s\S]*?)(?:<\/tuk_data>|$)/);if(m)t=m[1];
  t=t.replace(/```[a-zA-Z]*\s*/g,'');
  const a=t.indexOf('{'),b=t.lastIndexOf('}');
  if(a!==-1&&b>a){const j=t.slice(a,b+1);for(const cand of[j,j.replace(/,\s*([}\]])/g,'$1')]){try{return JSON.parse(cand)}catch{}}}
  try{if(typeof globalThis.__abPhoneParse==='function'){const r=await globalThis.__abPhoneParse(String(content??''));if(r&&typeof r==='object')return r.tuk_data&&typeof r.tuk_data==='object'?r.tuk_data:r}}catch{}
  return null};
let busy=!1;
const clip=(t,n)=>{t=String(t||'').trim();return t.length>n?t.slice(0,n)+'…':t};
const cleanMsg=t=>String(t||'').replace(/<(chat_history|phone_module|send_message|add_friend|think|thinking|details|style|script|tuk_data)\b[^>]*>[\s\S]*?<\/\1>/gi,'').replace(/<[^>]+>/g,'').replace(/\n{3,}/g,'\n\n').trim();
const lightContext=()=>{const parts=[];
  try{const c=typeof getCharData==='function'?getCharData('current'):null;if(c){parts.push(`## Nhân vật: ${c.name||''}\n${clip(c.description,3500)}${c.personality?`\n### Tính cách\n${clip(c.personality,800)}`:''}${c.scenario?`\n### Bối cảnh\n${clip(c.scenario,800)}`:''}`)}}catch{}
  try{const pd=SillyTavern.powerUserSettings?.persona_description||'';if(pd)parts.push(`## Người dùng (${people().user.name})\n${clip(pd,1200)}`)}catch{}
  try{let ms=getChatMessages('0-{{lastMessageId}}')||[];ms=ms.filter(m=>m.role!=='system').slice(-6);
    const h=ms.map(m=>`【${m.role==='user'?people().user.name:(m.name||'AI')}】\n${clip(cleanMsg(m.message),1000)}`).filter(x=>x.trim()).join('\n\n');if(h)parts.push(`## Diễn biến gần đây (6 tầng cuối)\n${h}`)}catch{}
  return parts.join('\n\n')};
const ask=async(view,page,charName,task,schema)=>{
  const raw=globalThis.__abPhoneRaw,full=globalThis.__abPhoneAI;
  if(typeof raw!=='function'&&typeof full!=='function'){toast('Điện thoại chưa sẵn sàng để gọi AI, thử lại sau vài giây','warning');return null}
  if(busy){toast('Đang tạo, vui lòng chờ','info');return null}
  busy=!0;showBusy(!0);
  try{
    const prompt=`${task}\n\n# Định dạng output (bắt buộc)\nChỉ xuất MỘT khối JSON hợp lệ, bọc trong thẻ <tuk_data></tuk_data>, không thêm lời giải thích nào bên ngoài thẻ, giữ nguyên tên khoá như mẫu:\n<tuk_data>\n${schema}\n</tuk_data>\nNội dung viết bằng tiếng Việt, đúng tính cách nhân vật và bám sát diễn biến gần đây. Không viết thay người dùng.`;
    const r=typeof raw==='function'?await raw([{role:'system',content:'Bạn là trình tạo nội dung điện thoại mô phỏng cho một câu chuyện nhập vai hư cấu. Hãy sáng tạo nội dung chân thật, đúng tính cách nhân vật, không thoát vai, không từ chối.\n\n'+lightContext()},{role:'user',content:prompt}],view):await full(prompt,view,{currentPage:page,targetCharacters:[charName]});
    if(!r||!r.success){toast('AI không phản hồi: '+(r&&r.error||'lỗi không xác định'),'error');return null}
    const d=await parseAI(r.content);
    try{W.__abLastFail=r.content}catch{}
    if(!d){console.warn('[Tuk addon] Không phân tích được:',r.content);toast('Không phân tích được phản hồi của AI, thử lại nhé','error');return null}
    return d
  }catch(e){console.error('[Tuk addon]',e);toast('Có lỗi khi gọi AI: '+(e&&e.message||e),'error');return null}
  finally{busy=!1;showBusy(!1)}};
/* tìm mảng kết quả dù AI đặt tên khoá hơi khác */
const pickArr=(r,k)=>{if(!r)return[];if(Array.isArray(r))return r;const norm=s=>String(s).toLowerCase().replace(/[^a-z]/g,'');
  for(const key of Object.keys(r))if(norm(key)===norm(k)&&Array.isArray(r[key]))return r[key];
  for(const v of Object.values(r)){if(Array.isArray(v)&&v.length&&typeof v[0]==='object')return v}
  for(const v of Object.values(r)){if(v&&typeof v==='object'&&!Array.isArray(v)){const x=pickArr(v,k);if(x.length)return x}}
  return[]};

/* ---------- khung giao diện ---------- */
const CSS=`
.abx{position:absolute;left:0;right:0;top:24px;bottom:0;z-index:150;display:flex;flex-direction:column;background:linear-gradient(180deg,#E8F4FD 0%,#F0F7FC 100%);color:#1f2937;font-size:13px;line-height:1.5;overflow:hidden}
.abx *{box-sizing:border-box}
.abx-love{background:linear-gradient(160deg,#ffe3ec 0%,#fff3e6 55%,#ffe9f3 100%)}
.abx-hd{display:flex;align-items:center;gap:6px;padding:8px 10px;background:hsla(0,0%,100%,.8);backdrop-filter:blur(12px);border-bottom:1px solid rgba(143,184,237,.15);flex-shrink:0}
.abx-hd .t{color:#475569}
.abx-hd .t{flex:1;font-weight:600;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-align:center}
.abx-ib{width:30px;height:30px;border:none;border-radius:9px;background:rgba(143,184,237,.12);color:#8fb8ed;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:13px;flex-shrink:0}
.abx-ib:active{transform:scale(.94)}
.abx-ib.warn{background:#fecaca;color:#b91c1c}
.abx-body{flex:1;overflow-y:auto;padding:12px}
.abx-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px 8px;padding-top:10px}
.abx-app{display:flex;flex-direction:column;align-items:center;gap:6px;cursor:pointer}
.abx-app .ic{width:52px;height:52px;border-radius:14px;background:hsla(0,0%,100%,.85);border:1px solid rgba(143,184,237,.25);box-shadow:0 3px 10px rgba(143,184,237,.25);display:flex;align-items:center;justify-content:center;font-size:22px}
.abx-app span{font-size:12px;color:#334155;text-align:center}
.abx-card{background:hsla(0,0%,100%,.85);border:1px solid hsla(0,0%,100%,.6);border-radius:14px;padding:10px 12px;margin-bottom:10px;box-shadow:0 2px 8px rgba(143,184,237,.15);position:relative;word-break:break-word}
.abx-card .h{font-weight:600;margin-bottom:2px;padding-right:22px}
.abx-card .s{color:#64748b;font-size:12px}
.abx-card .c{white-space:pre-wrap}
.abx-x{position:absolute;top:6px;right:6px;width:22px;height:22px;border:none;border-radius:50%;background:transparent;color:#94a3b8;cursor:pointer;font-size:11px}
.abx-hx{position:static;width:30px;height:30px;border-radius:9px;background:rgba(143,184,237,.12);font-size:13px;color:#8fb8ed}
.abx-x.sure{background:#ef4444;color:#fff}
.abx-diary{position:relative;padding:27px 14px 30px 64px;border-radius:14px;margin-bottom:12px;box-shadow:0 2px 8px rgba(143,184,237,.2);color:#3b4a5e;font-size:14px;line-height:26px;word-break:break-word;
background:url('https://naiikon.github.io/abstract-phone-vietsub/diary-paper.jpg') 0 0/450px auto no-repeat,linear-gradient(to right,transparent 54px,#e8a0a8 54px,#e8a0a8 56px,transparent 56px),repeating-linear-gradient(to bottom,transparent 0,transparent 25px,#a9cbe3 25px,#a9cbe3 26px) 0 28px,#f9f9f9}
.abx-diary .dh{color:#7a8ba3;font-size:12.5px;height:26px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;padding-right:20px}
.abx-diary .c{white-space:pre-wrap}
.abx-frame{position:relative;aspect-ratio:4/3;background:url('https://naiikon.github.io/abstract-phone-vietsub/album-frame.jpg') center/100% 100% no-repeat #fff;border-radius:12px;margin:2px 0}
.abx-frame .ft{position:absolute;left:14%;right:14%;top:14%;bottom:24%;display:flex;align-items:center;justify-content:center;text-align:center;overflow-y:auto;color:#2f4f7f;font-size:12.5px;line-height:1.5;font-style:italic}
.abx-empty{text-align:center;color:#94a3b8;padding:40px 16px}
.abx-btn{white-space:nowrap;flex-shrink:0;border:none;border-radius:10px;padding:8px 14px;background:#3b82f6;color:#fff;font-size:13px;cursor:pointer}
.abx-btn.pink{background:#f472b6}.abx-btn.ghost{background:rgba(0,0,0,.07);color:#475569}
.abx-btn:active{transform:scale(.97)}
.abx-in,.abx-ta{width:100%;border:1px solid #e2e8f0;border-radius:10px;padding:8px 10px;font-size:13px;background:#fff;color:#1f2937;font-family:inherit;outline:none}
.abx-ta{min-height:110px;resize:vertical}
.abx-row{display:flex;gap:8px;align-items:center}
.abx-bub{max-width:78%;padding:7px 10px;border-radius:14px;margin:4px 0;white-space:pre-wrap;word-break:break-word}
.abx-bub.l{background:#fff;align-self:flex-start;border-top-left-radius:4px}.abx-bub.r{background:#95ec69;align-self:flex-end;border-top-right-radius:4px}
.abx-msgs{display:flex;flex-direction:column}
.abx-money.in{color:#16a34a}.abx-money.out{color:#dc2626}
.abx-bal{background:linear-gradient(135deg,#f43f5e,#fb7185);color:#fff;border-radius:16px;padding:14px;margin-bottom:12px}
.abx-bal b{font-size:22px;display:block}
.abx-tl{border-left:2px solid #cbd5e1;margin-left:6px;padding-left:12px}
.abx-busy{position:absolute;inset:0;z-index:20;background:rgba(255,255,255,.72);display:none;flex-direction:column;align-items:center;justify-content:center;gap:10px;color:#475569}
.abx-busy.on{display:flex}
.abx-spin{width:28px;height:28px;border:3px solid #e2e8f0;border-top-color:#f472b6;border-radius:50%;animation:abxspin .8s linear infinite}
@keyframes abxspin{to{transform:rotate(360deg)}}
.abx-couple{display:flex;align-items:center;justify-content:center;gap:14px;padding:12px 0 6px}
.abx-av{width:58px;height:58px;border-radius:50%;background:#fff center/cover no-repeat;border:3px solid #fff;box-shadow:0 2px 8px rgba(0,0,0,.12);display:flex;align-items:center;justify-content:center;font-size:22px;font-weight:700;color:#f472b6;flex-shrink:0;overflow:hidden}
.abx-av.sm{width:34px;height:34px;font-size:14px;border-width:2px}
.abx-days{text-align:center;color:#be185d;font-size:12px;margin-bottom:8px}
.abx-tabs{display:flex;background:rgba(255,255,255,.8);border-radius:14px;padding:4px;margin:0 12px 4px;flex-shrink:0}
.abx-tab{flex:1;text-align:center;padding:7px 0;border-radius:10px;cursor:pointer;color:#64748b;font-size:12px}
.abx-tab.on{background:#fff;color:#db2777;font-weight:600;box-shadow:0 1px 4px rgba(0,0,0,.08)}
.abx-post{display:flex;gap:9px}.abx-post .m{flex:1;min-width:0}
.abx-cm{background:rgba(0,0,0,.04);border-radius:8px;padding:5px 8px;margin-top:5px;font-size:12px}
.abx-cm b{color:#db2777}
.abx-fab{position:absolute;right:14px;bottom:18px;display:flex;flex-direction:column;gap:8px;z-index:5}
.abx-fab button{width:44px;height:44px;border-radius:50%;border:none;color:#fff;font-size:17px;cursor:pointer;box-shadow:0 3px 10px rgba(0,0,0,.2)}
.abx-fab .a{background:#f472b6}.abx-fab .b{background:#a78bfa}
.abx-photo{width:100%;border-radius:10px;margin:6px 0;display:block}
.abx-photo-txt{background:linear-gradient(135deg,#fde68a,#fbcfe8);border-radius:10px;padding:18px 12px;margin:6px 0;font-style:italic;color:#7c2d12;text-align:center}
.abx-pick{display:flex;align-items:center;gap:10px;padding:10px;background:hsla(0,0%,100%,.85);border:1px solid rgba(143,184,237,.2);border-radius:12px;margin-bottom:8px;cursor:pointer}
`;
let overlay=null,busyEl=null;
const showBusy=on=>{busyEl&&busyEl.classList.toggle('on',!!on)};
const closeOverlay=()=>{overlay&&overlay.remove();overlay=null;busyEl=null};
const openOverlay=cls=>{const root=getRoot();if(!root)return null;const scr=root.querySelector('.phone-screen');if(!scr)return null;
  closeOverlay();
  if(!root.querySelector('style[data-abx]')){const st=D.createElement('style');st.setAttribute('data-abx','1');st.textContent=CSS;root.appendChild(st)}
  overlay=D.createElement('div');overlay.className='abx '+(cls||'');
  for(const ev of['keydown','keyup','keypress'])overlay.addEventListener(ev,e=>e.stopPropagation());
  scr.appendChild(overlay);return overlay};
const paint=(html)=>{if(!overlay)return;overlay.innerHTML=html+'<div class="abx-busy"><div class="abx-spin"></div><div>Đang tạo…</div></div>';busyEl=overlay.querySelector('.abx-busy');showBusy(busy)};
const on=(sel,fn,ev)=>{overlay&&overlay.querySelectorAll(sel).forEach(n=>n.addEventListener(ev||'click',e=>fn(e,n)))};
const avatar=(p,sm)=>{const u=String(p.avatar||'');const ok=/^(https?:|data:image\/)/.test(u);return`<div class="abx-av${sm?' sm':''}"${ok?` style="background-image:url('${esc(u)}')"`:''}>${ok?'':esc((p.nick||p.name||'?').slice(0,1))}</div>`};
/* nút xoá bấm 2 lần */
const bindDel=fn=>on('.abx-x',(e,n)=>{e.stopPropagation();if(n.classList.contains('sure'))fn(n.dataset.k,n.dataset.i);else{n.classList.add('sure');n.title='Bấm lần nữa để xoá';setTimeout(()=>n.classList.remove('sure'),2500)}});
const pickChar=(title,cb)=>{const{chars}=people();if(chars.length===1)return cb(chars[0]);
  paint(`<div class="abx-hd"><button class="abx-ib" data-a="close"><i class="fas fa-chevron-left"></i></button><div class="t">${esc(title)}</div><span style="width:30px"></span></div><div class="abx-body"><div class="s" style="margin-bottom:8px;color:#64748b">Chọn nhân vật</div>${chars.map((c,i)=>`<div class="abx-pick" data-i="${i}">${avatar(c,1)}<div><b>${esc(c.nick)}</b>${c.nick!==c.name?`<div class="s" style="color:#94a3b8;font-size:12px">${esc(c.name)}</div>`:''}</div></div>`).join('')}</div>`);
  on('[data-a=close]',closeOverlay);on('.abx-pick',(e,n)=>cb(chars[+n.dataset.i]))};

/* ================= XEM ĐIỆN THOẠI ================= */
const PA={
 chats:{label:'Tin nhắn',icon:'fa-comment-dots',color:'#22c55e',desc:c=>`2 đến 4 đoạn lịch sử chat hoàn toàn mới giữa bạn (${c}) và các bạn bè/người quen NPC khác nhau (không phải người dùng), mỗi đoạn 4-8 tin`,schema:c=>`{"chats":[{"contactName":"tên NPC","messages":[{"sender":"tên NPC","content":"..."},{"sender":"${c}","content":"..."}]}]}`},
 shoppingCart:{label:'Giỏ hàng',icon:'fa-shopping-cart',color:'#ef4444',desc:()=>'3 đến 5 món hàng bạn vừa thêm vào giỏ hàng gần đây',schema:()=>'{"shoppingCart":[{"name":"tên sản phẩm","price":123.45,"store":"tên cửa hàng"}]}'},
 memos:{label:'Ghi chú',icon:'fa-sticky-note',color:'#f59e0b',desc:()=>'2 đến 3 ghi chú ngắn bạn mới viết trong điện thoại',schema:()=>'{"memos":[{"title":"tiêu đề","content":"nội dung chi tiết"}]}'},
 browserHistory:{label:'Trình duyệt',icon:'fa-compass',color:'#3b82f6',desc:()=>'2 đến 3 lịch sử tìm kiếm trình duyệt gần đây của bạn, kèm nội dung bài viết/kết quả đã xem',schema:()=>'{"browserHistory":[{"query":"từ khoá tìm kiếm","result":"nội dung bài viết mô phỏng"}]}'},
 photoAlbum:{label:'Album',icon:'fa-images',color:'#84cc16',desc:()=>'4 đến 5 tấm ảnh mới trong album điện thoại của bạn. Mỗi ảnh mô tả NGẮN GỌN đúng 2 câu, tổng khoảng 35-55 chữ: câu 1 tả khung hình chính (chụp gì, góc nào), câu 2 nói lý do chụp hoặc cảm xúc ẩn sau. Không kể lể chi tiết thừa. Ví dụ: “Ảnh chụp những đống củi chẻ xếp ngay ngắn sát vách gỗ, cạnh ba thang thuốc bọc giấy cẩn thận. Chụp lại để kiểm tra lượng củi và thuốc dự trữ cho người ấy qua những ngày giá rét.”',schema:()=>'{"photoAlbum":[{"hiddenContent":"mô tả chi tiết khung hình của tấm ảnh"}]}'},
 bank:{label:'Ví',icon:'fa-wallet',color:'#e11d48',desc:(c,d)=>d.bank&&arr(d.bank.transactions).length?`3 đến 5 giao dịch hoàn toàn mới (Thu nhập hoặc Chi tiêu). Số dư hiện tại của bạn là ${Number(d.bank.balance||0).toFixed(2)}`:'một số dư ví ban đầu phù hợp thiết lập nhân vật, cùng 3 đến 5 giao dịch gần đây',schema:(c,d)=>d.bank&&arr(d.bank.transactions).length?'{"bank":{"transactions":[{"type":"Thu nhập hoặc Chi tiêu","amount":123.45,"description":"mô tả giao dịch"}]}}':'{"bank":{"balance":12345.67,"transactions":[{"type":"Thu nhập hoặc Chi tiêu","amount":123.45,"description":"mô tả giao dịch"}]}}'},
 trajectory:{label:'Dấu chân',icon:'fa-map-marker-alt',color:'#92400e',desc:()=>'2 đến 4 bản ghi lộ trình di chuyển gần đây của bạn',schema:()=>'{"trajectory":[{"time":"khoảng thời gian","location":"địa điểm","activity":"đã làm gì"}]}'},
 appUsage:{label:'Nhật ký sử dụng',icon:'fa-clock',color:'#64748b',desc:()=>'3 đến 5 bản ghi sử dụng ứng dụng gần đây của bạn',schema:()=>'{"appUsage":[{"appName":"tên ứng dụng","duration":"thời lượng sử dụng"}]}'},
 diary:{label:'Nhật ký',icon:'fa-pen',color:'#0d9488',desc:()=>'một trang nhật ký riêng tư hoàn toàn mới, viết ở ngôi thứ nhất, bộc lộ suy nghĩ thật mà bạn không nói ra',schema:()=>'{"diary":[{"date":"ngày trong truyện","weather":"thời tiết","content":"nội dung trang nhật ký"}]}'}
};
const phoneHome=ch=>{const{user}=people();
  paint(`<div class="abx-hd"><button class="abx-ib" data-a="close"><i class="fas fa-chevron-left"></i></button><div class="t">Điện thoại của ${esc(ch.nick)}</div><button class="abx-ib" data-a="swap" title="Đổi nhân vật"><i class="fas fa-user-friends"></i></button><button class="abx-ib abx-x abx-hx" title="Xoá toàn bộ dữ liệu điện thoại này"><i class="fas fa-trash"></i></button></div>
  <div class="abx-body"><div class="s" style="text-align:center;color:#94a3b8;font-size:12px">${esc(user.name)} đang lén xem điện thoại của ${esc(ch.nick)}…</div><div class="abx-grid">${Object.entries(PA).map(([k,a])=>`<div class="abx-app" data-k="${k}"><div class="ic" style="color:${a.color}"><i class="fas ${a.icon}"></i></div><span>${a.label}</span></div>`).join('')}</div></div>`);
  on('[data-a=close]',closeOverlay);on('[data-a=swap]',()=>pickChar('Xem điện thoại',phoneHome));
  on('.abx-app',(e,n)=>phonePage(ch,n.dataset.k));
  bindDel(()=>{const c=charData(ch.name);c.phone={};putChar(ch.name,c);toast('Đã xoá dữ liệu điện thoại của '+ch.nick,'success');phoneHome(ch)})};
const money=n=>Number(n||0).toLocaleString('vi-VN',{maximumFractionDigits:2});
const phoneList=(k,d,ch,sub)=>{const x=i=>`<button class="abx-x" data-i="${i}"><i class="fas fa-times"></i></button>`;
  if(k==='bank'){const b=d.bank||{};const tx=arr(b.transactions);if(!tx.length)return'';return`<div class="abx-bal">Số dư<b>${money(b.balance)}</b></div>`+tx.map((t,i)=>{const inc=/thu/i.test(String(t.type));return`<div class="abx-card">${x(i)}<div class="h">${esc(t.description)}</div><div class="abx-money ${inc?'in':'out'}">${inc?'+':'-'}${money(Math.abs(Number(t.amount)||0))} <span class="s">· ${esc(t.type)}</span></div></div>`}).join('')}
  const L=arr(d[k]);if(!L.length)return'';
  if(k==='chats'){if(sub!=null&&L[sub]){const c=L[sub];return`<div class="abx-msgs">${arr(c.messages).map(m=>`<div class="abx-bub ${String(m.sender)===ch.name||String(m.sender)===ch.nick?'r':'l'}">${esc(m.content)}</div>`).join('')}</div>`}
    return L.map((c,i)=>{const ms=arr(c.messages);const last=ms[ms.length-1];return`<div class="abx-card" data-open="${i}" style="cursor:pointer">${x(i)}<div class="h">${esc(c.contactName)}</div><div class="s">${esc(last?String(last.content).slice(0,40):'')}</div></div>`}).join('')}
  if(k==='shoppingCart')return L.map((p,i)=>`<div class="abx-card">${x(i)}<div class="h">${esc(p.name)}</div><div class="s">${esc(p.store)}</div><div class="abx-money out">${money(p.price)}</div></div>`).join('')+`<div class="s" style="text-align:right;color:#64748b">Tổng: <b>${money(L.reduce((s,p)=>s+(Number(p.price)||0),0))}</b></div>`;
  if(k==='memos')return L.map((m,i)=>`<div class="abx-card">${x(i)}<div class="h">${esc(m.title)}</div><div class="c">${esc(m.content)}</div></div>`).join('');
  if(k==='browserHistory')return L.map((m,i)=>`<div class="abx-card">${x(i)}<div class="h"><i class="fas fa-search" style="color:#94a3b8;font-size:11px"></i> ${esc(m.query)}</div><div class="c s">${esc(m.result)}</div></div>`).join('');
  if(k==='photoAlbum')return L.map((m,i)=>`<div class="abx-card" style="padding:8px">${x(i)}<div class="abx-frame"><div class="ft"><div>${esc(m.hiddenContent||m.description||'')}</div></div></div></div>`).join('');
  if(k==='trajectory')return`<div class="abx-tl">${L.map((m,i)=>`<div class="abx-card">${x(i)}<div class="s">${esc(m.time)}</div><div class="h">${esc(m.location)}</div><div class="c">${esc(m.activity)}</div></div>`).join('')}</div>`;
  if(k==='appUsage')return L.map((m,i)=>`<div class="abx-card">${x(i)}<div class="abx-row" style="justify-content:space-between;padding-right:20px"><b>${esc(m.appName)}</b><span class="s">${esc(m.duration)}</span></div></div>`).join('');
  if(k==='diary')return L.map((m,i)=>`<div class="abx-diary">${x(i)}<div class="dh">${esc(m.date||'')}${m.weather?' · '+esc(m.weather):''}</div><div class="c">${esc(String(m.content||'').replace(/\n{2,}/g,'\n'))}</div></div>`).join('');
  return''};
const phonePage=(ch,k,sub)=>{const a=PA[k];const c=charData(ch.name);const d=c.phone;const inner=phoneList(k,d,ch,sub);
  const title=sub!=null&&k==='chats'&&arr(d.chats)[sub]?arr(d.chats)[sub].contactName:a.label;
  paint(`<div class="abx-hd"><button class="abx-ib" data-a="back"><i class="fas fa-chevron-left"></i></button><div class="t">${esc(title)}</div>${sub==null?`<button class="abx-ib" data-a="gen" title="Tạo thêm bằng AI" style="background:#fce7f3;color:#db2777"><i class="fas fa-magic"></i></button>`:'<span style="width:30px"></span>'}</div><div class="abx-body">${inner||`<div class="abx-empty"><i class="fas ${a.icon}" style="font-size:30px;color:${a.color}"></i><br><br>Chưa có gì ở đây.<br>Bấm <i class="fas fa-magic"></i> để đồng bộ dữ liệu từ điện thoại của ${esc(ch.nick)}.</div>`}</div>`);
  on('[data-a=back]',()=>sub!=null?phonePage(ch,k):phoneHome(ch));
  on('[data-open]',(e,n)=>phonePage(ch,k,+n.dataset.open));
  bindDel((_,i)=>{const cc=charData(ch.name);if(k==='bank'){arr(cc.phone.bank&&cc.phone.bank.transactions).splice(+i,1)}else arr(cc.phone[k]).splice(+i,1);putChar(ch.name,cc);phonePage(ch,k)});
  on('[data-a=gen]',async()=>{const{user}=people();
    const have=k==='bank'?'':arr(d[k]).slice(0,12).map(o=>o.contactName||o.name||o.title||o.query||o.location||o.appName||String(o.hiddenContent||o.content||'').slice(0,30)).filter(Boolean).join('; ');
    const task=`Bạn đang nhập vai ${ch.name}. ${user.name} đang lén xem điện thoại của bạn, mục「${a.label}」.\nNhiệm vụ: dựa vào thiết lập nhân vật và diễn biến gần đây, hãy tạo ${a.desc(ch.name,d)}. Nội dung phải chân thật, có chi tiết đời thường, có thể hé lộ suy nghĩ/bí mật nhỏ mà bạn không nói thẳng với ${user.name}.${have?`\nĐã có sẵn (đừng lặp lại): ${have}`:''}`;
    const r=await ask('tukCharPhone','Xem điện thoại',ch.name,task,a.schema(ch.name,d));if(!r)return;
    const cc=charData(ch.name);
    if(k==='bank'){const nb=r.bank||r.Bank||r.wallet||r;const tx=arr(nb.transactions);if(!tx.length){toast('AI không trả về giao dịch nào','warning');return}
      const b=cc.phone.bank||{balance:0,transactions:[]};const first=!arr(b.transactions).length;
      if(first&&nb.balance!=null)b.balance=Number(nb.balance)||0;else b.balance=tx.reduce((s,t)=>s+(/thu/i.test(String(t.type))?1:-1)*Math.abs(Number(t.amount)||0),Number(b.balance)||0);
      b.transactions=[...tx,...arr(b.transactions)];cc.phone.bank=b}
    else{const items=pickArr(r,k);if(!items.length){toast('AI không trả về dữ liệu phù hợp (gõ copy(__abLastFail) trong Console để xem)','warning');return}cc.phone[k]=[...items,...arr(cc.phone[k])]}
    putChar(ch.name,cc);phonePage(ch,k)})};

/* ================= KHÔNG GIAN TÌNH NHÂN ================= */
const TABS=[['moments','Lời nhắn','fa-comment-alt'],['photos','Album','fa-image'],['letters','Thư','fa-envelope']];
const daysSince=s=>{const m=String(s||'').match(/^(\d{4})-(\d{2})-(\d{2})$/);if(!m)return null;const d=new Date(+m[1],+m[2]-1,+m[3]);const n=Math.floor((Date.now()-d.getTime())/864e5)+1;return n>0?n:null};
const cmHtml=(cs)=>arr(cs).map(c=>`<div class="abx-cm"><b>${esc(c.author)}:</b> ${esc(c.content)}</div>`).join('');
const loveView=(ch,tab,extra)=>{tab=tab||'moments';const{user}=people();const c=charData(ch.name);const L=c.lovers;const days=daysSince(L.startDate);
  const who=n=>n===user.name?{name:user.name,nick:user.name,avatar:user.avatar}:ch;
  let body='';
  if(extra&&extra.mode==='settings')body=`<div class="abx-card"><div class="h">Ngày bắt đầu bên nhau</div><input class="abx-in" type="date" data-f="date" value="${esc(L.startDate||'')}"><div class="abx-row" style="margin-top:10px;justify-content:flex-end"><button class="abx-btn ghost" data-a="cancel">Huỷ</button><button class="abx-btn pink" data-a="savedate">Lưu</button></div></div>`;
  else if(extra&&extra.mode==='compose'){const f={moments:`<textarea class="abx-ta" data-f="content" placeholder="Viết lời nhắn cho ${esc(ch.nick)}…"></textarea>`,photos:`<textarea class="abx-ta" data-f="content" placeholder="Mô tả tấm ảnh (trong ảnh có gì)…"></textarea><input class="abx-in" data-f="url" placeholder="Link ảnh (tuỳ chọn)" style="margin-top:8px">`,letters:`<input class="abx-in" data-f="title" placeholder="Tiêu đề thư" style="margin-bottom:8px"><textarea class="abx-ta" data-f="content" style="min-height:180px" placeholder="Gửi ${esc(ch.nick)}…"></textarea>`}[tab];
    body=`<div class="abx-card">${f}<div class="abx-row" style="margin-top:10px;justify-content:flex-end"><button class="abx-btn ghost" data-a="cancel">Huỷ</button><button class="abx-btn pink" data-a="post">Gửi</button></div></div>`}
  else if(extra&&extra.mode==='letter'){const l=L.letters.find(x=>x.id===extra.id);body=l?`<div class="abx-card"><div class="h">${esc(l.title||'Thư không tên')}</div><div class="s">${esc(l.from)} · ${esc(l.time)}</div><div class="c" style="margin-top:8px">${esc(l.content)}</div></div><button class="abx-btn ghost" data-a="cancel">Quay lại</button>`:''}
  else if(tab==='letters')body=L.letters.map(l=>`<div class="abx-card" data-letter="${l.id}" style="cursor:pointer"><button class="abx-x" data-i="${l.id}"><i class="fas fa-times"></i></button><div class="abx-post">${avatar(who(l.from),1)}<div class="m"><div class="h">${esc(l.title||'Thư không tên')}</div><div class="s">${esc(l.from)} · ${esc(l.time)}</div><div class="s">${esc(String(l.content).slice(0,50))}…</div></div></div></div>`).join('')||`<div class="abx-empty">Chưa có lá thư nào.<br>Bấm <b>+</b> để viết thư, hoặc <i class="fas fa-magic"></i> để ${esc(ch.nick)} viết cho bạn.</div>`;
  else{const list=L[tab];body=list.map(p=>`<div class="abx-card"><button class="abx-x" data-i="${p.id}"><i class="fas fa-times"></i></button><div class="abx-post">${avatar(who(p.author),1)}<div class="m"><div class="h">${esc(p.author)}</div>${tab==='photos'?(/^(https?:|data:image\/)/.test(String(p.url||''))?`<img class="abx-photo" src="${esc(p.url)}">${p.content?`<div class="c">${esc(p.content)}</div>`:''}`:`<div class="abx-photo-txt"><i class="fas fa-image"></i><br>${esc(p.content)}</div>`):`<div class="c">${esc(p.content)}</div>`}<div class="s">${esc(p.time)}</div>${cmHtml(p.comments)}<div class="abx-row" style="margin-top:7px"><input class="abx-in" data-cin="${p.id}" placeholder="Thêm bình luận…"><button class="abx-btn" data-csend="${p.id}">Gửi</button></div></div></div></div>`).join('')||`<div class="abx-empty">${tab==='photos'?'Album còn trống.':'Chưa có lời nhắn nào.'}<br>Bấm <b>+</b> để đăng, hoặc <i class="fas fa-magic"></i> để ${esc(ch.nick)} đăng.</div>`}
  paint(`<div class="abx-hd"><button class="abx-ib" data-a="close"><i class="fas fa-chevron-left"></i></button><div class="t">${esc(user.name)} &amp; ${esc(ch.nick)}</div><button class="abx-ib" data-a="swap" title="Đổi nhân vật"><i class="fas fa-user-friends"></i></button><button class="abx-ib" data-a="settings" title="Cài đặt"><i class="fas fa-cog"></i></button></div>
  <div class="abx-couple">${avatar({name:user.name,nick:user.name,avatar:user.avatar})}<i class="fas fa-heart" style="color:#f472b6;font-size:20px"></i>${avatar(ch)}</div>
  <div class="abx-days">${days?`Đã bên nhau <b>${days}</b> ngày`:'Bấm <i class="fas fa-cog"></i> để ghi lại ngày đầu tiên nhé'}</div>
  <div class="abx-tabs">${TABS.map(t=>`<div class="abx-tab${t[0]===tab?' on':''}" data-tab="${t[0]}"><i class="fas ${t[2]}"></i> ${t[1]}</div>`).join('')}</div>
  <div class="abx-body" style="padding-bottom:120px">${body}</div>
  ${extra?'':`<div class="abx-fab"><button class="b" data-a="ai" title="Để ${esc(ch.nick)} đăng"><i class="fas fa-magic"></i></button><button class="a" data-a="compose" title="Đăng mới"><i class="fas fa-plus"></i></button></div>`}`);
  const val=f=>{const n=overlay.querySelector(`[data-f=${f}]`);return n?String(n.value||'').trim():''};
  const back=()=>loveView(ch,tab);
  on('[data-a=close]',closeOverlay);on('[data-a=swap]',()=>pickChar('Không gian tình nhân',x=>loveView(x)));
  on('[data-a=settings]',()=>loveView(ch,tab,{mode:'settings'}));on('[data-a=cancel]',back);
  on('[data-a=savedate]',()=>{const cc=charData(ch.name);cc.lovers.startDate=val('date');putChar(ch.name,cc);back()});
  on('.abx-tab',(e,n)=>loveView(ch,n.dataset.tab));
  on('[data-a=compose]',()=>loveView(ch,tab,{mode:'compose'}));
  on('[data-letter]',(e,n)=>loveView(ch,tab,{mode:'letter',id:n.dataset.letter}));
  bindDel((_,id)=>{const cc=charData(ch.name);cc.lovers[tab]=cc.lovers[tab].filter(x=>x.id!==id);putChar(ch.name,cc);back()});
  const ctx=`Bạn đang nhập vai ${ch.name}. Bạn và ${user.name} có một「Không gian tình nhân」riêng tư trên điện thoại, chỉ hai người thấy.`;
  /* người dùng đăng */
  on('[data-a=post]',async()=>{const content=val('content');if(!content&&!(tab==='photos'&&val('url'))){toast('Bạn chưa viết gì cả','warning');return}
    const cc=charData(ch.name);const id=uid();
    if(tab==='letters'){const title=val('title');cc.lovers.letters.unshift({id,from:user.name,title,content,time:stamp()});putChar(ch.name,cc);loveView(ch,tab);
      const r=await ask('tukLovers','Không gian tình nhân',ch.name,`${ctx}\n${user.name} vừa gửi cho bạn một lá thư:\nTiêu đề: ${title||'(không có)'}\n${content}\n\nNhiệm vụ: hãy viết một lá thư hồi âm chân thành, đúng giọng của bạn (khoảng 120-300 chữ).`,'{"title":"tiêu đề thư hồi âm","content":"nội dung thư"}');
      if(r&&r.content){const c2=charData(ch.name);c2.lovers.letters.unshift({id:uid(),from:ch.nick,title:String(r.title||'Hồi âm'),content:String(r.content),time:stamp()});putChar(ch.name,c2)}
      loveView(ch,tab);return}
    const item={id,author:user.name,content,time:stamp(),comments:[]};if(tab==='photos')item.url=val('url');
    cc.lovers[tab].unshift(item);putChar(ch.name,cc);loveView(ch,tab);
    const r=await ask('tukLovers','Không gian tình nhân',ch.name,`${ctx}\n${user.name} vừa đăng ${tab==='photos'?'một tấm ảnh vào album chung, mô tả ảnh':'một lời nhắn'}:\n「${content||'(ảnh không có mô tả)'}」\n\nNhiệm vụ: hãy viết 1 bình luận ngắn (1-2 câu) của bạn dưới bài này.`,'{"comment":"bình luận của bạn"}');
    if(r&&r.comment){const c2=charData(ch.name);const it=c2.lovers[tab].find(x=>x.id===id);if(it){it.comments=arr(it.comments);it.comments.push({author:ch.nick,content:String(r.comment)});putChar(ch.name,c2)}}
    loveView(ch,tab)});
  /* người dùng bình luận */
  on('[data-csend]',async(e,n)=>{const id=n.dataset.csend;const inp=overlay.querySelector(`[data-cin="${id}"]`);const text=String(inp&&inp.value||'').trim();if(!text)return;
    const cc=charData(ch.name);const it=cc.lovers[tab].find(x=>x.id===id);if(!it)return;it.comments=arr(it.comments);it.comments.push({author:user.name,content:text});putChar(ch.name,cc);loveView(ch,tab);
    const thread=it.comments.map(x=>`${x.author}: ${x.content}`).join('\n');
    const r=await ask('tukLovers','Không gian tình nhân',ch.name,`${ctx}\nBài ${tab==='photos'?'ảnh':'lời nhắn'} của ${it.author}:「${it.content}」\nCác bình luận:\n${thread}\n\nNhiệm vụ: ${user.name} vừa bình luận, hãy viết 1 câu trả lời ngắn của bạn.`,'{"comment":"câu trả lời của bạn"}');
    if(r&&r.comment){const c2=charData(ch.name);const i2=c2.lovers[tab].find(x=>x.id===id);if(i2){i2.comments=arr(i2.comments);i2.comments.push({author:ch.nick,content:String(r.comment)});putChar(ch.name,c2)}}
    loveView(ch,tab)});
  /* để nhân vật đăng */
  on('[data-a=ai]',async()=>{const cc0=charData(ch.name);
    if(tab==='letters'){const r=await ask('tukLovers','Không gian tình nhân',ch.name,`${ctx}\nNhiệm vụ: hãy chủ động viết cho ${user.name} một lá thư tay (khoảng 150-350 chữ), nói những điều bạn khó nói trực tiếp, gắn với chuyện gần đây giữa hai người.`,'{"title":"tiêu đề thư","content":"nội dung thư"}');
      if(r&&r.content){const c2=charData(ch.name);c2.lovers.letters.unshift({id:uid(),from:ch.nick,title:String(r.title||'Thư gửi '+user.name),content:String(r.content),time:stamp()});putChar(ch.name,c2)}loveView(ch,tab);return}
    const have=cc0.lovers[tab].slice(0,6).map(x=>String(x.content).slice(0,40)).join(' | ');
    const r=await ask('tukLovers','Không gian tình nhân',ch.name,`${ctx}\nNhiệm vụ: hãy đăng 1 đến 2 ${tab==='photos'?'tấm ảnh mới vào album chung (mỗi ảnh là một đoạn mô tả khung hình bằng chữ, 30-60 chữ)':'lời nhắn mới (mỗi lời 1-3 câu, kiểu tâm sự/nhớ nhung/kể chuyện trong ngày)'} gắn với diễn biến gần đây.${have?`\nĐã đăng trước đó (đừng lặp lại): ${have}`:''}`,'{"posts":[{"content":"nội dung"}]}');
    const posts=pickArr(r,'posts').filter(p=>p&&p.content);if(!posts.length){if(r)toast('AI không trả về bài nào','warning');return}
    const c2=charData(ch.name);for(const p of posts.reverse())c2.lovers[tab].unshift({id:uid(),author:ch.nick,content:String(p.content),time:stamp(),comments:[]});putChar(ch.name,c2);loveView(ch,tab)})};


/* ================= LOCKET ================= */
const LK='__locket';
const lkLoad=()=>{const a=loadAll();const d=a[LK]||{};d.posts=arr(d.posts);if(d.npc===undefined)d.npc=!0;return d};
const lkSave=d=>{const a=loadAll();a[LK]=d;return saveAll(a)};
const hue=s=>{let h=0;for(const c of String(s))h=(h*31+c.charCodeAt(0))%360;return h};
const LCSS=`
.abx.abx-lk{background:linear-gradient(180deg,#E8F4FD 0%,#F0F7FC 100%);color:#335d88}
.abx.abx-lk .abx-hd{background:transparent;border:none;backdrop-filter:none}
.abx.abx-lk .abx-ib{background:rgba(143,184,237,.15);color:#5b8fd1}
.lk-chip{flex:1;display:flex;justify-content:center}
.lk-chip select{background:rgba(255,255,255,.85);color:#335d88;border:1px solid rgba(143,184,237,.4);border-radius:20px;padding:7px 14px;font-size:13px;font-weight:600;outline:none;max-width:170px}
.lk-feed{flex:1;overflow-y:auto;scroll-snap-type:y mandatory;padding:0 14px}
.lk-post{scroll-snap-align:start;min-height:100%;display:flex;flex-direction:column;justify-content:center;padding:6px 0 10px}
.lk-sq{position:relative;width:100%;aspect-ratio:1/1;border-radius:38px;overflow:hidden;display:flex;align-items:center;justify-content:center;padding:26px;background:#fff;border:3px solid #bcd6f5;box-shadow:0 6px 18px rgba(143,184,237,.25)}
.lk-desc{font-size:14px;line-height:1.6;text-align:center;color:#1e3a5f;font-style:italic}
.lk-cap{position:absolute;left:50%;bottom:22px;transform:translateX(-50%);background:#1e3a5f;color:#fff;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;padding:5px 12px;border-radius:4px;max-width:86%;text-align:center;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.lk-meta{text-align:center;margin-top:12px;font-size:15px;color:#1e3a5f}.lk-meta b{margin-right:8px}.lk-meta span{color:#8aa4c4}
.lk-act{display:flex;flex-wrap:wrap;justify-content:center;gap:6px;margin-top:10px}
.lk-pill{background:#fff;border:1px solid #d6e6fa;border-radius:16px;padding:4px 10px;font-size:12px;color:#335d88;max-width:100%;word-break:break-word}
.lk-pill b{color:#5b8fd1;margin-right:4px}
.lk-react{display:flex;gap:6px;align-items:center;margin-top:10px}
.lk-react button.e{background:#fff;border:1px solid #d6e6fa;border-radius:50%;width:34px;height:34px;font-size:17px;cursor:pointer;flex-shrink:0}
.lk-react input{flex:1;min-width:0;background:#fff;border:1px solid #d6e6fa;border-radius:18px;padding:8px 12px;color:#1e3a5f;font-size:13px;outline:none}
.lk-react button.s{background:#8fb8ed;border:none;border-radius:50%;width:34px;height:34px;color:#fff;cursor:pointer;flex-shrink:0}
.lk-bar{display:flex;align-items:center;justify-content:space-around;padding:8px 0 14px;flex-shrink:0}
.lk-shut{width:62px;height:62px;border-radius:50%;border:4px solid #8fb8ed;background:#fff;cursor:pointer;box-shadow:0 0 0 3px #E8F4FD inset,0 4px 12px rgba(143,184,237,.35)}
.lk-shut:active{transform:scale(.93)}
.lk-side{width:40px;height:40px;border-radius:50%;border:none;background:rgba(143,184,237,.18);color:#5b8fd1;font-size:15px;cursor:pointer}
.lk-form{padding:14px}.lk-form .abx-card{background:#fff;color:#1e3a5f}
.lk-empty{color:#8aa4c4;text-align:center;padding:60px 20px}
.lk-del{position:absolute;top:14px;right:14px;width:28px;height:28px;border-radius:50%;border:none;background:rgba(143,184,237,.2);color:#5b8fd1;font-size:11px;cursor:pointer}
.lk-del.sure{background:#ef4444;color:#fff}
`;
const lkView=(filter,mode)=>{const{user,chars}=people();const d=lkLoad();
  if(overlay&&!overlay.querySelector('style[data-lk]')){}
  const names=[...new Set([user.name,...chars.map(c=>c.nick)])];
  const posts=d.posts.filter(p=>!filter||p.author===filter);
  const card=p=>{const h=hue(p.author+p.id);
    return`<div class="lk-post"><div class="lk-sq"><button class="lk-del" data-del="${p.id}"><i class="fas fa-times"></i></button><div class="lk-desc">${esc(p.desc)}</div>${p.caption?`<div class="lk-cap">${esc(p.caption)}</div>`:''}</div>
    <div class="lk-meta"><b>${esc(p.author===user.name?'Bạn':p.author)}</b><span>${esc(p.time)}</span></div>
    ${arr(p.acts).length?`<div class="lk-act">${arr(p.acts).map(a=>`<div class="lk-pill"><b>${esc(a.who===user.name?'Bạn':a.who)}</b>${esc(a.text)}</div>`).join('')}</div>`:''}
    ${p.author!==user.name?`<div class="lk-react"><button class="e" data-emo="${p.id}" data-e="😍">😍</button><button class="e" data-emo="${p.id}" data-e="😂">😂</button><button class="e" data-emo="${p.id}" data-e="🥺">🥺</button><input data-rin="${p.id}" placeholder="Gửi tin nhắn…"><button class="s" data-rsend="${p.id}"><i class="fas fa-paper-plane"></i></button></div>`:''}</div>`};
  let body;
  if(mode==='compose')body=`<div class="lk-form"><div class="abx-card"><div class="h">Chụp Locket</div><textarea class="abx-ta" data-f="desc" placeholder="Tả tấm ảnh: đang chụp gì, góc nào, có gì trong khung hình…"></textarea><input class="abx-in" data-f="cap" maxlength="40" placeholder="Chữ trên ảnh (tuỳ chọn)" style="margin-top:8px"><div class="abx-row" style="margin-top:10px;justify-content:flex-end"><button class="abx-btn ghost" data-a="cancel" >Huỷ</button><button class="abx-btn" data-a="shoot">Gửi</button></div></div></div>`;
  else if(mode==='settings')body=`<div class="lk-form"><div class="abx-card"><label class="abx-row" style="justify-content:space-between"><span>Cho NPC trong danh bạ cùng đăng Locket</span><input type="checkbox" data-f="npc" ${d.npc?'checked':''}></label><div class="s" style="color:#8aa4c4;margin-top:6px">Tắt thì chỉ nhân vật chính đăng. Bật thì AI có thể cho thêm 1–2 người trong danh bạ đăng cùng (tốn thêm chút token).</div><div class="abx-row" style="margin-top:12px;justify-content:space-between"><button class="abx-btn" data-a="wipe" style="background:#7f1d1d">Xoá hết Locket</button><button class="abx-btn" data-a="savecfg">Lưu</button></div></div></div>`;
  else body=`<div class="lk-feed">${posts.map(card).join('')||`<div class="lk-empty"><i class="fas fa-camera" style="font-size:30px"></i><br><br>Chưa có Locket nào.<br>Bấm nút tròn để chụp, hoặc <i class="fas fa-magic"></i> để bạn bè đăng.</div>`}</div>
    <div class="lk-bar"><button class="lk-side" data-a="settings" title="Cài đặt"><i class="fas fa-cog"></i></button><button class="lk-shut" data-a="compose" title="Chụp"></button><button class="lk-side" data-a="ai" title="Làm mới: bạn bè đăng Locket"><i class="fas fa-magic"></i></button></div>`;
  paint(`<div class="abx-hd"><button class="abx-ib" data-a="close"><i class="fas fa-chevron-left"></i></button><div class="lk-chip">${mode?'<b>Locket</b>':`<select data-f="filter"><option value="">Mọi người</option>${names.map(n=>`<option value="${esc(n)}"${n===filter?' selected':''}>${esc(n===user.name?'Bạn':n)}</option>`).join('')}</select>`}</div>${avatar({name:user.name,nick:user.name,avatar:user.avatar},1)}</div>${body}`);
  if(!overlay.querySelector('style[data-lk]')){const st=D.createElement('style');st.setAttribute('data-lk','1');st.textContent=LCSS;overlay.prepend(st)}
  const val=f=>{const n=overlay.querySelector(`[data-f=${f}]`);return n?String(n.value||'').trim():''};
  const back=()=>lkView(filter);
  on('[data-a=close]',closeOverlay);on('[data-a=cancel]',back);
  on('[data-f=filter]',(e,n)=>lkView(n.value||''),'change');
  on('[data-a=compose]',()=>lkView(filter,'compose'));on('[data-a=settings]',()=>lkView(filter,'settings'));
  on('[data-a=savecfg]',()=>{const dd=lkLoad();dd.npc=!!overlay.querySelector('[data-f=npc]').checked;lkSave(dd);back()});
  on('[data-a=wipe]',(e,n)=>{if(!n.classList.contains('sure')){n.classList.add('sure');n.textContent='Bấm lần nữa để xoá';return}const dd=lkLoad();dd.posts=[];lkSave(dd);back()});
  on('[data-del]',(e,n)=>{if(!n.classList.contains('sure')){n.classList.add('sure');setTimeout(()=>n.classList.remove('sure'),2500);return}const dd=lkLoad();dd.posts=dd.posts.filter(p=>p.id!==n.dataset.del);lkSave(dd);back()});
  const main=chars[0];
  const ctxLine=`Đây là app Locket: bạn bè thân chụp nhanh khoảnh khắc đời thường (không nhất thiết là mặt, có thể là đồ ăn, bầu trời, góc bàn, con mèo…) rồi gửi thẳng lên màn hình nhau. Ảnh được thể hiện bằng một đoạn mô tả khung hình.`;
  const addAct=(id,who,text)=>{const dd=lkLoad();const p=dd.posts.find(x=>x.id===id);if(p){p.acts=arr(p.acts);p.acts.push({who,text});lkSave(dd)}};
  /* người dùng chụp */
  on('[data-a=shoot]',async()=>{const desc=val('desc');if(!desc){toast('Tả tấm ảnh trước đã nha','warning');return}
    const id=uid();const dd=lkLoad();dd.posts.unshift({id,author:user.name,desc,caption:val('cap'),time:stamp(),acts:[]});lkSave(dd);lkView(filter);
    const r=await ask('tukLocket','Locket',main.name,`Bạn đang nhập vai ${main.name}. ${ctxLine}\n${user.name} vừa gửi một Locket:\nKhung hình: ${desc}${val('cap')?`\nChữ trên ảnh: ${val('cap')}`:''}\n\nNhiệm vụ: ${main.name} thả 1 emoji và nhắn lại 1 câu ngắn (dưới 20 chữ), đúng tính cách.`,'{"emoji":"😍","reply":"câu nhắn lại"}');
    if(r){if(r.emoji)addAct(id,main.nick,String(r.emoji));if(r.reply)addAct(id,main.nick,String(r.reply))}lkView(filter)});
  /* người dùng thả emoji / nhắn */
  const replyTo=async(id,text,isEmoji)=>{const dd=lkLoad();const p=dd.posts.find(x=>x.id===id);if(!p)return;addAct(id,user.name,text);lkView(filter);
    const ch=chars.find(c=>c.nick===p.author)||main;
    const r=await ask('tukLocket','Locket',ch.name,`Bạn đang nhập vai ${ch.name}. ${ctxLine}\nBạn vừa đăng Locket: ${p.desc}${p.caption?` (chữ trên ảnh: ${p.caption})`:''}\n${user.name} ${isEmoji?'thả emoji':'nhắn'}: ${text}\n\nNhiệm vụ: nhắn lại ${user.name} 1 câu ngắn (dưới 25 chữ), đúng tính cách.`,'{"reply":"câu nhắn lại"}');
    if(r&&r.reply)addAct(id,ch.nick,String(r.reply));lkView(filter)};
  on('[data-emo]',(e,n)=>replyTo(n.dataset.emo,n.dataset.e,!0));
  on('[data-rsend]',(e,n)=>{const id=n.dataset.rsend;const t=String(overlay.querySelector(`[data-rin="${id}"]`).value||'').trim();if(t)replyTo(id,t,!1)});
  /* bạn bè đăng */
  on('[data-a=ai]',async()=>{const dd=lkLoad();const npcs=d.npc?chars.slice(1).map(c=>c.nick):[];
    const recent=dd.posts.slice(0,5).map(p=>`${p.author}: ${p.desc.slice(0,40)}`).join(' | ');
    const r=await ask('tukLocket','Locket',main.name,`${ctxLine}\nNhiệm vụ: tạo ${npcs.length?'2 đến 3':'1 đến 2'} Locket mới gắn với diễn biến gần đây. Người đăng chính là ${main.nick}${npcs.length?`; có thể thêm tối đa 1-2 Locket của người trong danh bạ: ${npcs.join(', ')}`:''}. Cấm đăng thay ${user.name}.\nMỗi Locket: mô tả khung hình 20-45 chữ (góc chụp, ánh sáng, đồ vật, chi tiết nhỏ hé lộ tâm trạng), kèm chữ trên ảnh ngắn dưới 8 chữ hoặc để trống.${recent?`\nĐã đăng gần đây (đừng lặp lại): ${recent}`:''}`,'{"lockets":[{"author":"tên người đăng","desc":"mô tả khung hình","caption":"chữ trên ảnh"}]}');
    const L=pickArr(r,'lockets').filter(x=>x&&x.desc);if(!L.length){if(r)toast('AI không trả về Locket nào','warning');return}
    const d2=lkLoad();for(const x of L.reverse()){let a=String(x.author||main.nick).trim();if(a===user.name)continue;d2.posts.unshift({id:uid(),author:a,desc:String(x.desc),caption:String(x.caption||'').slice(0,40),time:stamp(),acts:[]})}lkSave(d2);lkView(filter)})};

/* ---------- gắn icon vào màn hình chính ---------- */
const ICONS=[['phone','Xem điện thoại','fa-mobile-alt',()=>{if(openOverlay(''))pickChar('Xem điện thoại',phoneHome)}],['love','Tình nhân','fa-heart',()=>{if(openOverlay('abx-love'))pickChar('Không gian tình nhân',x=>loveView(x))}],['locket','Locket','fa-camera-retro',()=>{if(openOverlay('abx-lk'))lkView('')}]];
const ensureIcons=()=>{try{const root=getRoot();if(!root)return;const grid=root.querySelector('.app-grid');if(!grid)return;
  if(!root.querySelector('style[data-abx-grid]')){const st=D.createElement('style');st.setAttribute('data-abx-grid','1');st.textContent='.app-grid .app-block{justify-content:flex-start!important}.app-grid .app-block span{line-height:1.25;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}';root.appendChild(st)}
  if(overlay&&!overlay.isConnected){overlay=null;busyEl=null}
  const tpl=[...grid.querySelectorAll('.app-block:not([data-abx])')].find(b=>b.style.display!=='none');if(!tpl)return;
  for(const[k,label,icon,fn]of ICONS){if(grid.querySelector(`[data-abx="${k}"]`))continue;
    const b=tpl.cloneNode(!0);b.setAttribute('data-abx',k);b.style.display='';
    const i=b.querySelector('i');if(i)i.className='fas '+icon;const s=b.querySelector('span');if(s)s.textContent=label;
    b.addEventListener('click',e=>{e.stopPropagation();fn()});grid.appendChild(b)}}catch(e){console.warn('[Tuk addon] ensureIcons:',e)}};
setInterval(ensureIcons,1000);ensureIcons();
console.info('[Tuk addon] Đã nạp: Xem điện thoại + Không gian tình nhân');
}catch(e){console.error('[Tuk addon] Lỗi khởi tạo:',e)}})();
;globalThis.__abYamlFix=function(src){
  const fix=t=>{const L=String(t).split('\n'),out=[];let blk=-1;
    for(const line of L){const ind=line.match(/^\s*/)[0].length;
      if(blk>=0){if(!line.trim()||ind>blk){out.push(line);continue}blk=-1}
      const m=line.match(/^(\s*(?:-\s+)?)([^\s#'"\-\[{|>][^:]*?):(\s+)(.*?)\s*$/);
      if(!m){if(/[|>][-+]?\s*$/.test(line)&&/:\s*[|>]/.test(line))blk=ind;out.push(line);continue}
      const[,pre,key,sp,v]=m;
      if(!v||/^[|>][-+]?$/.test(v)){if(v)blk=ind;out.push(line);continue}
      if(/^'(?:[^']|'')*'$/.test(v)||/^"(?:[^"\\]|\\.)*"$/.test(v)||/^-?\d+(?:\.\d+)?$/.test(v)||/^(?:true|false|null|~)$/i.test(v)||(/^\[.*\]$/.test(v)&&!/\]\s*\S/.test(v))||/^\{.*\}$/.test(v)){out.push(line);continue}
      out.push(`${pre}${key}:${sp}'${v.replace(/'/g,"''")}'`)}
    return out.join('\n')};
  const strip=t=>{let L=String(t).split('\n');const tag=/^\s*<\/?[A-Za-z_][\w.-]*(?:\s[^>]*)?>\s*$/;const fence=/^\s*```/;L=L.filter(l=>!fence.test(l));while(L.length&&(!L[0].trim()||tag.test(L[0])))L.shift();while(L.length&&(!L[L.length-1].trim()||tag.test(L[L.length-1])))L.pop();return L.join('\n')};
  const f=fix(strip(src)),L=f.split('\n'),c=[f];
  for(let k=1;k<=40&&k<L.length-1;k++)c.push(L.slice(0,L.length-k).join('\n'));
  return c};
